steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "
      {
        teams(name: \"Web\") {
          nodes {
            id
            name
            workflowStates(states: [completed]) {
              nodes {
                id
                name
                type
              }
            }
          }
        }
        users(firstName: \"Priya\", lastName: \"Nair\") {
          nodes {
            id
            name
            firstName
            lastName
          }
        }
      }
    '
  '
